"""SR-CHURN-CUT 3: generated files are regenerated by CI from main and never carried in a PR diff.

Claims, one oracle each (a planted reversion of the named production line fails the named test):
  1. the registry lists exactly ci_generated.OUTPUTS plus the derived plan closure (a new output that is not registered fails)
  2. a path is generated iff the registry says so, and agrees with ci_generated.changed_outputs on the compiled tree
  3. CLOSURE_v3.json is a pure function of plan_model.json + ACCEPTANCE_ROOTS (kyclosure.compute, source: closure procedure of
     relaunch plan v2.2 §0): same inputs → same bytes; a changed depends_on edge changes it; a refused model refuses it
  4. ci_generated owns the closure: it is in OUTPUTS, so a PR carrying it is refused and the overlay manifest must contain it
  5. the PR guard refuses a diff that carries a generated path, accepts a diff that does not
  6. executor pin shards are append-only: adding one passes, editing/removing/renaming a merged one is refused
  7. `filter` prints exactly the non-generated names (the cockpit's patch-id input)
"""
import importlib.util
import json
import os
import shutil
import subprocess
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[4]
GOV = ROOT / 'platform/scripts/governance'
sys.path.insert(0, str(GOV))
import generated_paths as gp  # noqa: E402


def ci_generated():
    spec = importlib.util.spec_from_file_location('ci_generated_for_test', GOV / 'ci_generated.py')
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def test_registry_is_exactly_the_ci_outputs_plus_the_derived_closure():  # claim 1
    reg = gp.load()
    assert set(reg['paths']) == set(ci_generated().OUTPUTS) | {d['path'] for d in reg['derived']}
    assert len(reg['paths']) == len(set(reg['paths']))
    assert [d['path'] for d in reg['derived']] == [gp.CLOSURE]


def test_membership_agrees_with_the_compiled_tree_rules_and_leaves_sources_alone():  # claim 2
    reg, mod = gp.load(), ci_generated()
    for path in reg['paths']:
        assert gp.is_generated(path, reg), path
    for path in ('platform/src/generated/handmade.ts', 'platform/src/generated/projections/x.generated.json'):
        assert gp.is_generated(path, reg) is bool(mod.changed_outputs([path])), path
    for path in ('platform/src/generated/__tests__/new.test.ts', 'platform/src/generated/harvest/e2_db_truth.json',
                 'platform/src/generated/nirmana-analysis-layer-pins.json', 'platform/src/real_source.ts',
                 '00_ARCHITECTURE/control/kalayantra/plan_model.json',
                 '00_ARCHITECTURE/briefs/kalayantra/fleet/executor_ops.json'):
        assert not gp.is_generated(path, reg), path
    assert not {h['path'] for h in reg['hand_authored_hotspots']} & set(reg['paths'])


def _tree(tmp_path, mutate=None):
    """A copy of just the closure's inputs, so the derivation is exercised on a model we control."""
    control = '00_ARCHITECTURE/control/kalayantra/'
    (tmp_path / control).mkdir(parents=True)
    model = json.loads((ROOT / gp.MODEL).read_text(encoding='utf-8'))
    if mutate:
        mutate(model)
    (tmp_path / gp.MODEL).write_text(json.dumps(model), encoding='utf-8')
    roots = model['control_plane']['triage']['roots']
    shutil.copyfile(ROOT / roots, tmp_path / roots)
    return tmp_path


def test_closure_is_a_pure_function_of_the_model_and_roots(tmp_path):  # claim 3
    a = gp.closure_bytes(_tree(tmp_path / 'a'))
    assert a == gp.closure_bytes(_tree(tmp_path / 'b'))
    # the plan closure procedure: every member's depends_on edge is followed, so dropping one edge on the path to a root shrinks the closure
    root_items = [r['item'] for acc in json.loads((ROOT / json.loads((ROOT / gp.MODEL).read_text())['control_plane']['triage']['roots']).read_text())['acceptances'] for r in acc['roots']]
    victim = next(i for i in json.loads((ROOT / gp.MODEL).read_text())['items'] if i['id'] == 'C-1')

    def drop_edges(model):
        for item in model['items']:
            if item['id'] == victim['id']:
                item['depends_on'] = [d for d in item['depends_on'] if d not in root_items]
    assert gp.closure_bytes(_tree(tmp_path / 'c', drop_edges)) != a

    def break_model(model):
        model['items'].append(dict(model['items'][0]))   # duplicate id: kyclosure.model_findings refuses it
    with pytest.raises(ValueError, match='duplicate item id'):
        gp.closure_bytes(_tree(tmp_path / 'd', break_model))


def test_the_closure_is_a_ci_output_so_a_pr_cannot_carry_it_and_the_overlay_must_hold_it(tmp_path):  # claim 4
    mod = ci_generated()
    assert gp.CLOSURE in mod.OUTPUTS and mod.changed_outputs([gp.CLOSURE])
    doc = mod.manifest(ROOT, 'a' * 40, [p for p in mod.OUTPUTS if (ROOT / p).is_file()])
    assert gp.CLOSURE in doc['files']


GIT_ENV = {k: v for k, v in os.environ.items() if not k.startswith('GIT_')}
GIT_ENV.update(GIT_CONFIG_GLOBAL=os.devnull, GIT_CONFIG_NOSYSTEM='1', GIT_AUTHOR_NAME='f', GIT_AUTHOR_EMAIL='f@example.invalid',
               GIT_COMMITTER_NAME='f', GIT_COMMITTER_EMAIL='f@example.invalid')


def git(repo, *args):
    return subprocess.check_output(['git', '-C', str(repo), *args], env=GIT_ENV, text=True).strip()


@pytest.fixture()
def repo(tmp_path):
    r = tmp_path / 'repo'
    r.mkdir()
    git(r, 'init', '-q', '-b', 'main')
    reg = r / 'platform/scripts/governance/generated_paths.json'
    reg.parent.mkdir(parents=True)
    shutil.copyfile(GOV / 'generated_paths.json', reg)
    shard = r / gp.SHARD_DIR / 'K0-OLD.json'
    shard.parent.mkdir(parents=True)
    shard.write_text('{}\n')
    (r / 'src.txt').write_text('1\n')
    git(r, 'add', '-A')
    git(r, 'commit', '-q', '-m', 'base')
    base = git(r, 'rev-parse', 'HEAD')
    git(r, 'checkout', '-q', '-b', 'pr')
    return r, base


def commit(r, files, remove=()):
    for rel, text in files.items():
        (r / rel).parent.mkdir(parents=True, exist_ok=True)
        (r / rel).write_text(text)
    for rel in remove:
        (r / rel).unlink()
    git(r, 'add', '-A')
    git(r, 'commit', '-q', '-m', 'pr')


def test_pr_guard_refuses_a_carried_generated_path_and_accepts_a_clean_diff(repo):  # claim 5
    r, base = repo
    commit(r, {'src.txt': '2\n', gp.SHARD_DIR + 'K9-99.json': '{}\n'})
    assert gp.check(r, base) == []
    commit(r, {gp.CLOSURE: '{}\n'})
    errors = gp.check(r, base)
    assert len(errors) == 1 and gp.CLOSURE in errors[0]


def test_pin_shards_are_append_only(repo):  # claim 6
    r, base = repo
    commit(r, {gp.SHARD_DIR + 'K9-99.json': '{}\n'})
    assert gp.check(r, base) == []
    commit(r, {gp.SHARD_DIR + 'K0-OLD.json': '{"edited": true}\n'})
    assert any('K0-OLD' in e for e in gp.check(r, base))
    commit(r, {}, remove=[gp.SHARD_DIR + 'K0-OLD.json'])
    assert any('K0-OLD' in e for e in gp.check(r, base))


def test_filter_prints_only_the_names_that_are_not_generated():  # claim 7
    names = ['src.py', gp.CLOSURE, 'platform/src/generated/capability_estate_census.json', '00_ARCHITECTURE/control/kalayantra/plan_model.json']
    out = subprocess.run([sys.executable, str(GOV / 'generated_paths.py'), 'filter'], input='\n'.join(names) + '\n',
                         capture_output=True, text=True, check=True).stdout.split()
    assert out == ['src.py', '00_ARCHITECTURE/control/kalayantra/plan_model.json']
